use super::*;
fn cube(bounds:[Point;2])->SolidMesh{let[a,b]=bounds;SolidMesh{vertices:vec![[a[0],a[1],a[2]],[b[0],a[1],a[2]],[b[0],b[1],a[2]],[a[0],b[1],a[2]],[a[0],a[1],b[2]],[b[0],a[1],b[2]],[b[0],b[1],b[2]],[a[0],b[1],b[2]]],triangles:vec![[0,2,1],[0,3,2],[4,5,6],[4,6,7],[0,1,5],[0,5,4],[1,2,6],[1,6,5],[2,3,7],[2,7,6],[3,0,4],[3,4,7]]}}
fn measure(mesh:&SolidMesh)->f64{mesh.triangles.iter().map(|ids|{let[a,b,c]=ids.map(|i|mesh.vertices[i as usize]);dot(a,cross(b,c))/6.}).sum()}
#[test]
fn language_neutral_closed_solid_differences(){let fixtures=semio_framework_pack_json::parse(include_str!("🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in fixtures["cases"].as_array().unwrap(){let bounds=|key:&str|[0,1].map(|side|[0,1,2].map(|axis|row[key][side][axis].as_f64().unwrap()));let left=cube(bounds("host"));let right=cube(bounds("cut"));let result=subtract_solid(&left,&right,SolidBooleanLimits::default(),&mut ||Ok(())).unwrap();assert!((measure(&result)-row["volume"].as_f64().unwrap()).abs()<1e-8,"{}",row["name"]);let mut edges:BTreeMap<(u32,u32),(usize,i32)>=BTreeMap::new();for ids in &result.triangles{for i in 0..3{let(a,b)=(ids[i],ids[(i+1)%3]);let entry=edges.entry(edge_key(a,b)).or_default();entry.0+=1;entry.1+=if a<b{1}else{-1};}}assert!(edges.values().all(|value|*value==(2,0)));}}
#[test]
fn invalid_operands_and_all_caller_limits_fail_atomically(){let left=cube([[0.;3],[4.;3]]);let right=cube([[1.;3],[3.;3]]);let mut open=right.clone();open.triangles.remove(0);assert!(subtract_solid(&left,&open,SolidBooleanLimits::default(),&mut ||Ok(())).unwrap_err().contains("closed-manifold"));assert!(subtract_solid(&left,&right,SolidBooleanLimits{work:1,..SolidBooleanLimits::default()},&mut ||Ok(())).unwrap_err().contains("work-limit"));assert!(subtract_solid(&left,&right,SolidBooleanLimits{polygons:1,..SolidBooleanLimits::default()},&mut ||Ok(())).unwrap_err().contains("polygon-limit"));let mut calls=0;assert_eq!(subtract_solid(&left,&right,SolidBooleanLimits::default(),&mut ||{calls+=1;if calls==20{Err("original-cancel".into())}else{Ok(())}}).unwrap_err(),"original-cancel");assert_eq!(calls,20);assert_eq!(left.triangles.len(),12);}
#[test]
fn closed_edge_incidence_cannot_admit_intersecting_or_wrongly_nested_shells(){fn join(mut a:SolidMesh,b:SolidMesh)->SolidMesh{let offset=a.vertices.len() as u32;a.vertices.extend(b.vertices);a.triangles.extend(b.triangles.into_iter().map(|t|t.map(|i|i+offset)));a}let left=cube([[0.;3],[4.;3]]);let far=cube([[10.;3],[11.;3]]);let crossing=join(left.clone(),cube([[2.;3],[6.;3]]));assert!(subtract_solid(&crossing,&far,SolidBooleanLimits::default(),&mut ||Ok(())).unwrap_err().contains("self-intersecting"));let nested=join(left.clone(),cube([[1.;3],[3.;3]]));assert!(subtract_solid(&nested,&far,SolidBooleanLimits::default(),&mut ||Ok(())).unwrap_err().contains("shell-winding"));let cavity=subtract_solid(&left,&cube([[1.;3],[3.;3]]),SolidBooleanLimits::default(),&mut ||Ok(())).unwrap();assert!((measure(&subtract_solid(&cavity,&far,SolidBooleanLimits::default(),&mut ||Ok(())).unwrap())-56.).abs()<1e-8);}

#[test]
fn boolean_defaults_match_owned_schema(){let schema=semio_framework_pack_json::parse(include_str!("../🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let limits=SolidBooleanLimits::default();assert_eq!(limits.work as u64,schema["definitions"]["Limits"]["default"]["maxWork"].as_u64().unwrap());assert_eq!(limits.polygons as u64,schema["definitions"]["Limits"]["default"]["maxPolygons"].as_u64().unwrap());assert_eq!(limits.depth as u64,schema["definitions"]["Limits"]["default"]["maxDepth"].as_u64().unwrap());}

#[test]
fn language_neutral_all_regularized_operations(){let fixtures=semio_framework_pack_json::parse(include_str!("operators.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in fixtures["cases"].as_array().unwrap(){let bounds=[0,1].map(|side|[0,1,2].map(|axis|row["cut"][side][axis].as_f64().unwrap()));for(operation,key)in [(SolidBooleanOperation::Difference,"difference"),(SolidBooleanOperation::Union,"union"),(SolidBooleanOperation::Intersection,"intersection")]{for reflected in [false,true]{let transform=|mut mesh:SolidMesh|{if reflected{for p in &mut mesh.vertices{*p=[-p[0]-100.,p[1]+50.,p[2]-20.];}for t in &mut mesh.triangles{t.swap(1,2);}}mesh};let left=transform(cube([[0.;3],[4.;3]]));let right=transform(cube(bounds));let result=boolean_solid(operation,&left,&right,SolidBooleanLimits::default(),&mut ||Ok(()));if let Some(expected)=row[key].as_f64(){assert!((measure(&result.unwrap())-expected).abs()<1e-8,"{} {key}",row["name"]);}else{assert!(result.is_err(),"{} {key}",row["name"]);}}}}}
#[test]
fn all_operators_retain_empty_admission_and_original_limits(){let a=cube([[0.;3],[4.;3]]);let b=cube([[2.,0.,0.],[6.,4.,4.]]);for op in [SolidBooleanOperation::Difference,SolidBooleanOperation::Union,SolidBooleanOperation::Intersection]{assert!(boolean_solid(op,&a,&b,SolidBooleanLimits{work:1,..SolidBooleanLimits::default()},&mut ||Ok(())).is_err());assert!(boolean_solid(op,&a,&b,SolidBooleanLimits{polygons:1,..SolidBooleanLimits::default()},&mut ||Ok(())).is_err());assert_eq!(boolean_solid(op,&a,&b,SolidBooleanLimits::default(),&mut ||Err("original-cancel".into())).unwrap_err(),"original-cancel");let empty=SolidMesh::default();let result=boolean_solid(op,&a,&empty,SolidBooleanLimits::default(),&mut ||Ok(())).unwrap();assert!((measure(&result)-if op==SolidBooleanOperation::Intersection{0.}else{64.}).abs()<1e-8);}}

#[test]
fn language_neutral_exact_halfspace_restrictions(){let fixtures=semio_framework_pack_json::parse(include_str!("halfspaces.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in fixtures["cases"].as_array().unwrap(){let point=|key:&str|[0,1,2].map(|i|row[key][i].as_f64().unwrap());let result=subtract_half_space(&cube([[0.;3],[4.;3]]),&SolidPlane{origin:point("origin"),normal:point("normal")},SolidBooleanLimits::default(),&mut ||Ok(())).unwrap();assert!((measure(&result)-row["volume"].as_f64().unwrap()).abs()<1e-8,"{}",row["name"]);}}
#[test]
fn halfspace_refuses_erased_slivers_invalid_operands_and_original_limits(){let a=cube([[0.;3],[1.;3]]);for offset in [1e-12,1e-10,1e-9]{let result=subtract_half_space(&a,&SolidPlane{origin:[offset,0.,0.],normal:[1.,0.,0.]},SolidBooleanLimits::default(),&mut ||Ok(()));assert!(result.unwrap_err().contains("ambiguous-halfspace"));}let a=cube([[0.;3],[4.;3]]);let plane=SolidPlane{origin:[0.,0.,2.],normal:[0.,0.,1.]};let mut open=a.clone();open.triangles.remove(0);assert!(subtract_half_space(&open,&plane,SolidBooleanLimits::default(),&mut ||Ok(())).is_err());assert!(subtract_half_space(&a,&plane,SolidBooleanLimits{work:1,..SolidBooleanLimits::default()},&mut ||Ok(())).unwrap_err().contains("work-limit"));assert_eq!(subtract_half_space(&a,&plane,SolidBooleanLimits::default(),&mut ||Err("original-cancel".into())).unwrap_err(),"original-cancel");}
#[test]
fn halfspace_caps_preserve_tunnel_and_cavity_shells(){let a=cube([[0.;3],[4.;3]]);for(b,expected)in [(cube([[1.,1.,-1.],[3.,3.,5.]]),24.),(cube([[1.;3],[3.;3]]),28.)]{let host=subtract_solid(&a,&b,SolidBooleanLimits::default(),&mut ||Ok(())).unwrap();let result=subtract_half_space(&host,&SolidPlane{origin:[0.,0.,2.],normal:[0.,0.,1.]},SolidBooleanLimits::default(),&mut ||Ok(())).unwrap();assert!((measure(&result)-expected).abs()<1e-8);}}
